def run_case(t: object, holder: object, spec: dict, reached: set) -> dict:
    """One case against `holder`'s function, with its artifact in a fresh test-owned directory; the launcher's seams recorded on `t`."""
    import copy, dataclasses, shutil, tempfile
    calls: list = []
    tmp = Path(tempfile.mkdtemp(prefix="syrd420-")).resolve()

    def norm(value):
        if isinstance(value, (list, tuple)):
            return [norm(v) for v in value]
        if isinstance(value, (set, frozenset)):
            return sorted(norm(v) for v in value)
        if isinstance(value, dict):
            return {str(k): norm(v) for k, v in sorted(value.items())}
        if dataclasses.is_dataclass(value) and not isinstance(value, type):
            return {"dataclass": type(value).__name__, **{f.name: norm(getattr(value, f.name)) for f in dataclasses.fields(value)}}
        if isinstance(value, Path):
            return "PATH " + norm(str(value))
        if isinstance(value, str):
            return value.replace(str(tmp), "TMP")
        return value

    def record(name, fn):
        def call(*args, **kwargs):
            reached.add(name)
            try:
                answer = fn(*args, **kwargs)
            except BaseException as exc:
                calls.append([name, norm(list(args)), norm(dict(sorted(kwargs.items()))), {"raised": type(exc).__name__}])
                raise
            calls.append([name, norm(list(args)), norm(dict(sorted(kwargs.items()))), norm(answer)])
            return answer
        return call

    names = [*FUNCTIONS, "AGY_SOURCE_ORIGINS", "PROJECT_DESIGN_FORBIDDEN_KEYS", "PROJECT_DESIGN_ARTIFACT_SCHEMA", "_load_json", "_expand_path", "_validate_project_slug",
             "validate_ticket_prefix", "_validate_new_project_cli", "_is_valid_owner_user_name", "_default_role_cli_pairs"]
    saved = {n: getattr(t, n) for n in names}
    saved_env = {k: os.environ.get(k) for k in ("HOME", "SYRD420_DIR")}
    try:
        os.environ["HOME"] = str(tmp / "home")
        os.environ["SYRD420_DIR"] = str(tmp / "envdir")
        under = {n: getattr(holder, n) for n in FUNCTIONS}
        on_launcher = {n: record(n, saved[n]) for n in [*FUNCTIONS, "_load_json", "_expand_path", "_validate_project_slug", "validate_ticket_prefix",
                                                        "_validate_new_project_cli", "_is_valid_owner_user_name", "_default_role_cli_pairs"]}
        on_launcher.update(spec.get("launcher", {}))
        for n, f in on_launcher.items():
            setattr(t, n, f)
        call = spec["call"]
        try:
            if call == "load":
                doc = copy.deepcopy(BASE_TOP)
                doc["project"] = copy.deepcopy(BASE_PROJECT)
                for k in spec.get("drop_top", []):
                    doc.pop(k, None)
                for k in spec.get("drop_project", []):
                    doc["project"].pop(k, None)
                doc.update(copy.deepcopy(spec.get("top", {})))
                if isinstance(doc.get("project"), dict):
                    for k, v in spec.get("project", {}).items():
                        if v is None:
                            doc["project"][k] = None
                        else:
                            doc["project"][k] = copy.deepcopy(v)
                folder = (tmp / "home" / "art") if spec.get("artifact_home") else (tmp / "art")
                folder.mkdir(parents=True)
                (folder / "p420.project.json").write_text(spec["raw"] if "raw" in spec else json.dumps(doc), encoding="utf-8")
                path = Path("~/art/p420.project.json") if spec.get("artifact_home") else folder / "p420.project.json"
                got = under["load_project_design_artifact"](path, **({"expected_project": spec["expected"]} if "expected" in spec else {}))
            elif call == "string":
                got = under["_artifact_string"](spec["raw"], spec["key"], path=tmp / "a.json", **({"default": spec["default"]} if "default" in spec else {}))
            elif call == "optional":
                got = under["_artifact_optional_string"](spec["raw"], spec["key"], path=tmp / "a.json", **({"default": spec["default"]} if "default" in spec else {}))
            elif call == "forbidden":
                got = under["_artifact_forbidden_keys"](spec["raw"])
            else:
                got = under["_artifact_role_value_pairs"](spec["raw"], path=tmp / "a.json", field="project.role_models")
            answer = norm(got)
        except AssertionError:
            raise
        except BaseException as exc:  # noqa: BLE001 -- the baseline's own answer, whatever it raises
            answer = {"raised": type(exc).__name__, "message": norm(str(exc))}
        return {"answer": answer, "calls": calls}
    finally:
        for n, f in saved.items():
            setattr(t, n, f)
        for k, v in saved_env.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        shutil.rmtree(tmp)
