def test_every_answer_is_the_baselines() -> None:
    check(sorted(CASES) == sorted(GOLDEN), "every measured case is asserted, and nothing else")
    for label, spec in CASES.items():
        for holder in (m, t):
            got = run(holder, spec)
            check(got == GOLDEN[label], f"{label} ({holder.__name__}): the baseline's answer, every call in order: {got}")


def test_the_rules_hold_in_the_measured_record() -> None:
    def answer(label):
        return GOLDEN[label]["answer"]

    for label in ("document: forbidden keys at the top", "document: forbidden keys in the project", "document: forbidden keys at both levels"):
        check("must not preconfigure stages or roles for new projects" in answer(label)["message"], f"{label}: refused before anything else is read")
    check(answer("identity: another requested project")["raised"] == "SystemExit", "an artifact for another project is refused")
    full = answer("document: a full artifact")
    check(full["implementer_roles"] == ["main", "ops"] and full["audit_roles"] == ["qa", "security"] and full["include_designer"] is False
          and ["main", "claude"] in full["role_clis"] and ["qa", "agy"] in full["role_clis"] and full["role_models"] == [["main", "opus"]]
          and full["capability_grants"]["agy_credential_source"] == "syrd420-human", f"roles deduplicated and lowered, choices applied, blanks dropped: {full}")
    check("cannot be both implementers and auditors" in answer("roles: a role both implementer and auditor")["message"], "no role is both an implementer and an auditor")
    check("plain Unix user name" in answer("grants: grants: an agy source that is not a user name")["message"], "the agy source is a plain user name or nothing")


def test_every_launcher_seam_is_reached() -> None:
    expected = {name for reads in SEAMS.values() for name in reads if callable(getattr(t, name, None)) and not isinstance(getattr(t, name), type)}
    check(expected <= REACHED, f"a recorder on the launcher reached every seam: missing {sorted(expected - REACHED)}")


STRUCTURE = ("test_the_module_loads_no_other_switchyard_module_at_import", "test_either_import_order_gives_one_set_of_objects_and_the_defaults",
             "test_the_seams_read_through_the_launcher_and_nothing_bound", "test_the_launcher_reexports_the_twelve_and_its_readers_reach_them_there")
LAST = ("test_every_launcher_seam_is_reached",)


def main() -> int:
    names = sorted(name for name, value in globals().items() if name.startswith("test_") and callable(value))
    for name in [*STRUCTURE, *(name for name in names if name not in STRUCTURE + LAST), *LAST]:
        globals()[name]()
    print(f"project_design_artifact_boundary_test: {CHECKS} checks ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
